# PowerShell betiği: aynı içerikli dosyaları bul ve kopyalar.txt'ye yaz

$files = Get-ChildItem -Path .\dosyalar -Recurse -File | Select-Object FullName, Length

# İçerik hash'lerini hesaplayıp eşleştir
$hashes = @{}

foreach ($file in $files) {
    if ($file.Length -eq 0) {
        $hash = "empty"
    } else {
        $hash = (Get-FileHash -Path $file.FullName -Algorithm SHA256).Hash
    }

    if (-not $hashes.ContainsKey($hash)) {
        $hashes[$hash] = @()
    }

    # Dosya yolu, hash'e göre gruplanacak
    $relativePath = $file.FullName.Replace((Resolve-Path .\dosyalar).Path.TrimEnd('\'), '').TrimStart('\')
    $relativePath = $relativePath -replace '\\', '/'
    $hashes[$hash] += $relativePath
}

# Grupları filtrele (en az 2 dosya olanlar)
$groups = $hashes.Values | Where-Object { $_.Length -ge 2 }

# Sonuçları sırala ve yazdır
$outputLines = @()
foreach ($group in $groups) {
    $sortedGroup = $group | Sort-Object
    $outputLines += ($sortedGroup -join ' | ')
}

# Alfabetik sırayla satırları sırala
$finalOutput = $outputLines | Sort-Object

# Dosyaya yaz
$finalOutput > kopyalar.txt

